-- The iḍāfa chapter as the books set it out (al-Ghalāyīnī, Jāmiʿ al-Durūs pp. 205–220; Ibn Yaʿīsh, Sharḥ al-Mufaṣṣal
-- vol. 2 pp. 125–204; al-Suyūṭī, Hamʿ al-Hawāmiʿ vol. 2): the ten iḍāfa terms GT lacked, each with its books' pages and
-- examples, and the books' pages for the iḍāfa terms it had. Re-runnable.

INSERT OR REPLACE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, short_en, definition_ar, definition_en, badge_color, badge_color_dark, badge_color_light, status, discipline, name_bare, band_key, tier, version, name_ur) VALUES ('GT:idafa_kind:bimana_kaf', 'idafa_kind', 'bimana_kaf', 'GT:idafa_kind:manawiya', 14, 'الإضافة بمعنى كاف التشبيه', 'annexation meaning “like”', 'simile', 'ما كانت على تقدير كاف التشبيه، وضابطها أن يُضاف المشبَّهُ به إلى المشبَّه، نحو «لؤلؤُ الدمعِ».', 'The second noun is likened to the first: the thing it is compared with is annexed to it — “the pearls of tears”.', '#59a0dc', '#59a0dc', '#065284', 'live', 'NH', 'الاضافه بمعنى كاف التشبيه', 'ism', 'expert', 1, 'اضافت بمعنیٔ کافِ تشبیہ');
DELETE FROM ar_ling_gram_term_example WHERE term_id = 'GT:idafa_kind:bimana_kaf' AND id LIKE 'GTX:idafa:%';
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:bimana_kaf:1', 'GT:idafa_kind:bimana_kaf', 'انتثرَ لؤلؤُ الدمعِ على وردِ الخدودِ', 'The pearls of tears scattered over the roses of the cheeks', 'book', NULL, 'al:GPG:1687:1734524#p207', 1);
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:bimana_kaf:2', 'GT:idafa_kind:bimana_kaf', 'جرى ذهبُ الأصيلِ على لُجَينِ الماءِ', 'The gold of the late afternoon ran over the silver of the water', 'poetry', NULL, 'al:GPG:1687:1734524#p207', 2);
INSERT OR REPLACE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, short_en, definition_ar, definition_en, badge_color, badge_color_dark, badge_color_light, status, discipline, name_bare, band_key, tier, version, name_ur) VALUES ('GT:idafa_kind:mubham', 'idafa_kind', 'mubham', 'GT:idafa_kind:manawiya', 15, 'المضاف المتوغّل في الإبهام', 'deeply vague first term', 'vague', 'إذا كان المضافُ متوغّلًا في الإبهام كغير ومثل وشبه ونظير، لم تُفِده إضافتُه إلى المعرفة تعريفًا، ولذا يُوصف به النكرة.', 'A first noun as vague as غير, مثل, شبه or نظير stays indefinite even when joined to a definite noun, so it can describe an indefinite one.', '#59a0dc', '#59a0dc', '#065284', 'live', 'NH', 'المضاف المتوغل في الابهام', 'ism', 'expert', 1, 'مبہم مضاف');
DELETE FROM ar_ling_gram_term_example WHERE term_id = 'GT:idafa_kind:mubham' AND id LIKE 'GTX:idafa:%';
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:mubham:1', 'GT:idafa_kind:mubham', 'جاءَ رجلٌ غيرُك، أو مثلُ سليمٍ، أو شبهُ خليلٍ', 'A man other than you came, or one like سليم, or one resembling خليل', 'book', NULL, 'al:GPG:1687:1734525#p208', 1);
INSERT OR REPLACE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, short_en, definition_ar, definition_en, badge_color, badge_color_dark, badge_color_light, status, discipline, name_bare, band_key, tier, version, name_ur) VALUES ('GT:idafa_kind:iktisab', 'idafa_kind', 'iktisab', NULL, 16, 'اكتساب المضاف من المضاف إليه', 'the first term takes on the second’s gender', 'takes on', 'قد يكتسب المضافُ التأنيثَ أو التذكيرَ من المضاف إليه إذا صحّ الاستغناءُ عنه وإقامةُ المضاف إليه مُقامه، نحو «قُطعتْ بعضُ أصابعه».', 'The first noun may take the second’s gender, when it could be dropped and the second stand in its place — “some of his fingers were cut” with a feminine verb.', '#59a0dc', '#59a0dc', '#065284', 'live', 'NH', 'اكتساب المضاف من المضاف اليه', 'ism', 'expert', 1, 'مضاف الیہ سے مضاف کا اکتساب');
DELETE FROM ar_ling_gram_term_example WHERE term_id = 'GT:idafa_kind:iktisab' AND id LIKE 'GTX:idafa:%';
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:iktisab:1', 'GT:idafa_kind:iktisab', 'يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا', 'The day each soul finds the good it did set before it', 'quran', '3:30', 'al:GPG:1687:1734528#p211', 1);
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:iktisab:2', 'GT:idafa_kind:iktisab', 'قُطعتْ بعضُ أصابعِه', 'Some of his fingers were cut', 'book', NULL, 'al:GPG:1687:1734527#p210', 2);
INSERT OR REPLACE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, short_en, definition_ar, definition_en, badge_color, badge_color_dark, badge_color_light, status, discipline, name_bare, band_key, tier, version, name_ur) VALUES ('GT:idafa_kind:hadhf_mudaf', 'idafa_kind', 'hadhf_mudaf', NULL, 17, 'حذف المضاف', 'dropping the first term', 'first dropped', 'إذا أُمن اللبسُ حُذف المضافُ وأُقيم المضافُ إليه مُقامه وأُعرب بإعرابه، نحو ﴿وَسۡـَٔلِ ٱلۡقَرۡيَةَ﴾ أي أهلَها.', 'When nothing is lost, the first noun is dropped and the second takes its place and its case — “ask the town”, meaning its people.', '#59a0dc', '#59a0dc', '#065284', 'live', 'NH', 'حذف المضاف', 'ism', 'expert', 1, 'مضاف کا حذف');
DELETE FROM ar_ling_gram_term_example WHERE term_id = 'GT:idafa_kind:hadhf_mudaf' AND id LIKE 'GTX:idafa:%';
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:hadhf_mudaf:1', 'GT:idafa_kind:hadhf_mudaf', 'وَسۡـَٔلِ ٱلۡقَرۡيَةَ ٱلَّتِي كُنَّا فِيهَا وَٱلۡعِيرَ ٱلَّتِيٓ أَقۡبَلۡنَا فِيهَا', 'Ask the town we were in, and the caravan we came with — its people', 'quran', '12:82', 'al:GPG:1687:1734530#p213', 1);
INSERT OR REPLACE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, short_en, definition_ar, definition_en, badge_color, badge_color_dark, badge_color_light, status, discipline, name_bare, band_key, tier, version, name_ur) VALUES ('GT:idafa_kind:hadhf_mudaf_ilayh', 'idafa_kind', 'hadhf_mudaf_ilayh', NULL, 18, 'حذف المضاف إليه', 'dropping the second term', 'second dropped', 'قد يُحذف المضاف إليه ويبقى المضاف على حاله استغناءً بما يدلّ عليه، نحو «ما كلُّ سوداءَ تمرةً ولا بيضاءَ شحمةً».', 'The second noun may be dropped when what is said shows it — “not every black thing is a date, nor every white thing fat”.', '#59a0dc', '#59a0dc', '#065284', 'live', 'NH', 'حذف المضاف اليه', 'ism', 'expert', 1, 'مضاف الیہ کا حذف');
DELETE FROM ar_ling_gram_term_example WHERE term_id = 'GT:idafa_kind:hadhf_mudaf_ilayh' AND id LIKE 'GTX:idafa:%';
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:hadhf_mudaf_ilayh:1', 'GT:idafa_kind:hadhf_mudaf_ilayh', 'ما كلُّ سوداءَ تمرةً ولا بيضاءَ شحمةً', 'Not every black thing is a date, nor every white thing fat', 'book', NULL, 'al:GPG:1687:1734530#p213', 1);
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:hadhf_mudaf_ilayh:2', 'GT:idafa_kind:hadhf_mudaf_ilayh', 'جاءَ غلامُ وأخو عليٍّ', 'علي’s servant-boy and his brother came', 'book', NULL, 'al:GPG:1687:1734530#p213', 2);
INSERT OR REPLACE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, short_en, definition_ar, definition_en, badge_color, badge_color_dark, badge_color_light, status, discipline, name_bare, band_key, tier, version, name_ur) VALUES ('GT:idafa_kind:lazim_mufrad', 'idafa_kind', 'lazim_mufrad', NULL, 19, 'ما يلازم الإضافة إلى المفرد', 'always annexed to a single word', 'always joined', 'من الأسماء ما لا ينفكّ عن الإضافة إلى المفرد: منه ما لا يُقطع عنها كعند ولدى وكلا وكلتا وسوى وذو، ومنه ما يُقطع عنها لفظًا لا معنًى ككلّ وبعض وقبل وبعد وأيّ.', 'Some nouns are never used without a second noun: عند, لدى, كلا, كلتا, سوى, ذو; others drop it in word only, its meaning still understood: كل, بعض, قبل, بعد, أي.', '#59a0dc', '#59a0dc', '#065284', 'live', 'NH', 'ما يلازم الاضافه الى المفرد', 'ism', 'expert', 1, 'مفرد کی طرف لازم الاضافت');
DELETE FROM ar_ling_gram_term_example WHERE term_id = 'GT:idafa_kind:lazim_mufrad' AND id LIKE 'GTX:idafa:%';
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:lazim_mufrad:1', 'GT:idafa_kind:lazim_mufrad', 'كِلۡتَا ٱلۡجَنَّتَيۡنِ ءَاتَتۡ أُكُلَهَا', 'Each of the two gardens gave its fruit', 'quran', '18:33', 'al:GPG:2470:2293306#p513', 1);
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:lazim_mufrad:2', 'GT:idafa_kind:lazim_mufrad', 'أَيّٗا مَّا تَدۡعُواْ فَلَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ', 'Whichever you call on, His are the most beautiful names', 'quran', '17:110', 'al:GPG:1687:1734534#p217', 2);
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:lazim_mufrad:3', 'GT:idafa_kind:lazim_mufrad', 'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمۡ أَشَدُّ عَلَى ٱلرَّحۡمَٰنِ عِتِيّٗا', 'Then We shall pull out of every group whichever of them was fiercest against the Most Merciful', 'quran', '19:69', 'al:GPG:1687:1734533#p216', 3);
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:lazim_mufrad:4', 'GT:idafa_kind:lazim_mufrad', 'وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰ', 'And to each God has promised the best', 'quran', '4:95', 'al:GPG:1687:1734535#p218', 4);
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:lazim_mufrad:5', 'GT:idafa_kind:lazim_mufrad', 'وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعۡضٖ', 'We have preferred some prophets over others', 'quran', '17:55', 'al:GPG:1687:1734535#p218', 5);
INSERT OR REPLACE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, short_en, definition_ar, definition_en, badge_color, badge_color_dark, badge_color_light, status, discipline, name_bare, band_key, tier, version, name_ur) VALUES ('GT:idafa_kind:lazim_jumla', 'idafa_kind', 'lazim_jumla', NULL, 20, 'ما يلازم الإضافة إلى الجملة', 'always annexed to a sentence', 'joined to a sentence', 'ما يلازم الإضافة إلى الجملة: إذ وحيث وتُضافان إلى الفعلية والاسمية، وإذا ولمّا وتُضافان إلى الفعلية، ومذ ومنذ ظرفين، وما كان اسمَ زمانٍ مبهمًا كيوم.', 'إذ and حيث are joined to a whole sentence, verbal or nominal; إذا and لمّا to a verbal one; and a vague word of time like يوم may be joined to a sentence too.', '#59a0dc', '#59a0dc', '#065284', 'live', 'NH', 'ما يلازم الاضافه الى الجمله', 'ism', 'expert', 1, 'جملے کی طرف لازم الاضافت');
DELETE FROM ar_ling_gram_term_example WHERE term_id = 'GT:idafa_kind:lazim_jumla' AND id LIKE 'GTX:idafa:%';
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:lazim_jumla:1', 'GT:idafa_kind:lazim_jumla', 'وَٱذۡكُرُوٓاْ إِذۡ كُنتُمۡ قَلِيلٗا فَكَثَّرَكُمۡ', 'Remember when you were few, and He made you many', 'quran', '7:86', 'al:GPG:1687:1734536#p219', 1);
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:lazim_jumla:2', 'GT:idafa_kind:lazim_jumla', 'وَٱذۡكُرُوٓاْ إِذۡ أَنتُمۡ قَلِيلٞ', 'Remember when you were few', 'quran', '8:26', 'al:GPG:1687:1734536#p219', 2);
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:lazim_jumla:3', 'GT:idafa_kind:lazim_jumla', 'فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُ', 'Come to them as God has commanded you', 'quran', '2:222', 'al:GPG:1687:1734536#p219', 3);
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:lazim_jumla:4', 'GT:idafa_kind:lazim_jumla', 'يَوۡمَ لَا يَنفَعُ مَالٞ وَلَا بَنُونَ', 'The day when neither wealth nor sons will help', 'quran', '26:88', 'al:GPG:1687:1734537#p220', 4);
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:lazim_jumla:5', 'GT:idafa_kind:lazim_jumla', 'هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدۡقُهُمۡ', 'This is the day the truthful are helped by their truth', 'quran', '5:119', 'al:GPG:1687:1734537#p220', 5);
INSERT OR REPLACE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, short_en, definition_ar, definition_en, badge_color, badge_color_dark, badge_color_light, status, discipline, name_bare, band_key, tier, version, name_ur) VALUES ('GT:idafa_kind:ya_mutakallim', 'idafa_kind', 'ya_mutakallim', NULL, 21, 'المضاف إلى ياء المتكلم', 'annexed to ياء المتكلم', 'to “my”', 'المضاف إلى ياء المتكلم يُكسر آخرُه لمناسبة الياء، إلا المثنّى والمجموع على حدّه والمقصور والمنقوص فيسكن آخره، والياءُ تُفتح أو تُسكَّن، وقد تُحذف مع كسر ما قبلها.', 'A noun joined to ياء المتكلم takes a كسرة before it, except a dual, a sound plural or a word ending in ألف or ياء; the ياء may be open or still, and is sometimes dropped.', '#59a0dc', '#59a0dc', '#065284', 'live', 'NH', 'المضاف الى ياء المتكلم', 'ism', 'expert', 1, 'یائے متکلم کی طرف مضاف');
DELETE FROM ar_ling_gram_term_example WHERE term_id = 'GT:idafa_kind:ya_mutakallim' AND id LIKE 'GTX:idafa:%';
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:ya_mutakallim:1', 'GT:idafa_kind:ya_mutakallim', 'فَبَشِّرۡ عِبَادِ', 'So give glad tidings to My servants — the ياء dropped', 'quran', '39:17', 'al:GPG:2470:2293324#p531', 1);
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:ya_mutakallim:2', 'GT:idafa_kind:ya_mutakallim', 'عصايَ · محيايَ', 'my staff · my living — the ألف kept before the ياء', 'book', NULL, 'al:GPG:2470:2293322#p529', 2);
INSERT OR REPLACE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, short_en, definition_ar, definition_en, badge_color, badge_color_dark, badge_color_light, status, discipline, name_bare, band_key, tier, version, name_ur) VALUES ('GT:idafa_kind:amm_khass', 'idafa_kind', 'amm_khass', NULL, 22, 'إضافة العامّ إلى الخاصّ', 'general annexed to particular', 'general to particular', 'يجوز أن يُضاف العامُّ إلى الخاصّ كيوم الجمعة وشهر رمضان، ولا يجوز العكس لعدم الفائدة.', 'A general word may be joined to a particular one — يوم الجمعة, شهر رمضان — but not the reverse, which tells nothing.', '#59a0dc', '#59a0dc', '#065284', 'live', 'NH', 'اضافه العام الى الخاص', 'ism', 'expert', 1, 'عام کی خاص کی طرف اضافت');
DELETE FROM ar_ling_gram_term_example WHERE term_id = 'GT:idafa_kind:amm_khass' AND id LIKE 'GTX:idafa:%';
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:amm_khass:1', 'GT:idafa_kind:amm_khass', 'يومُ الجمعةِ · شهرُ رمضانَ', 'The day of Friday · the month of رمضان', 'book', NULL, 'al:GPG:1687:1734529#p212', 1);
INSERT OR REPLACE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, short_en, definition_ar, definition_en, badge_color, badge_color_dark, badge_color_light, status, discipline, name_bare, band_key, tier, version, name_ur) VALUES ('GT:idafa_kind:adna_mulabasa', 'idafa_kind', 'adna_mulabasa', NULL, 23, 'الإضافة لأدنى ملابسة', 'annexation by the slightest link', 'slight link', 'قد يُضاف الشيءُ إلى الشيء لأدنى سببٍ بينهما، نحو «انتظرني مكانَك أمسِ»، وليس المكانُ ملكًا له ولا خاصًّا به.', 'A thing may be joined to another for the slightest reason between them — “wait for me at your place of yesterday”, though the place is not his.', '#59a0dc', '#59a0dc', '#065284', 'live', 'NH', 'الاضافه لادنى ملابسه', 'ism', 'expert', 1, 'ادنیٰ مناسبت سے اضافت');
DELETE FROM ar_ling_gram_term_example WHERE term_id = 'GT:idafa_kind:adna_mulabasa' AND id LIKE 'GTX:idafa:%';
INSERT INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:adna_mulabasa:1', 'GT:idafa_kind:adna_mulabasa', 'انتظرني مكانَكَ أمسِ', 'Wait for me at your place of yesterday', 'book', NULL, 'al:GPG:1687:1734529#p212', 1);

