-- عضيمة, Dirāsāt li-Uslūb al-Qurʾān vol. 10 pp. 262–265 (its iḍāfa overview): the Qurʾān's own places
INSERT OR REPLACE INTO ar_ling_gram_term (id, category_key, term_key, parent_term_id, term_order, name_ar, name_en, short_en, definition_ar, definition_en, badge_color, badge_color_dark, badge_color_light, status, discipline, name_bare, band_key, tier, version, name_ur) VALUES ('GT:idafa_kind:fasl', 'idafa_kind', 'fasl', NULL, 24, 'الفصل بين المتضايفين', 'separating the two terms', 'separated', 'لا يُفصل بين المضاف والمضاف إليه عند البصريين إلا بالظرف في ضرورة الشعر، وأجازه الكوفيون بغيره، واحتجّ ابن مالك بقراءة ابن عامر ﴿قَتۡلُ أَوۡلَٰدَهُمۡ شُرَكَآئِهِمۡ﴾.', 'Nothing may stand between the two nouns, said البصريون, except an adverb in verse; الكوفيون allowed more, and ابن مالك took the reading of ابن عامر at 6:137 as proof.', '#59a0dc', '#59a0dc', '#065284', 'live', 'NH', 'الفصل بين المتضايفين', 'ism', 'expert', 1, 'مضاف اور مضاف الیہ کے درمیان فصل');
DELETE FROM ar_ling_gram_term_example WHERE term_id = 'GT:idafa_kind:fasl' AND id LIKE 'GTX:idafa:%';
INSERT OR REPLACE INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:fasl:1', 'GT:idafa_kind:fasl', 'زُيِّنَ لِكَثِيرٍ مِّنَ ٱلْمُشْرِكِينَ قَتْلُ أَوْلَٰدَهُمْ شُرَكَآئِهِمْ', 'The reading of ابن عامر: their partners’ killing of their children, the object set between the two nouns', 'quran', '6:137', 'al:GPG:5264:4725394#v10p264', 1);
INSERT OR REPLACE INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:hadhf_mudaf:2', 'GT:idafa_kind:hadhf_mudaf', 'حذف المضاف في القرآن نيّفٌ على ألف موضع', 'ابن جني: the first noun is dropped in over a thousand places in the Qurʾān', 'book', NULL, 'al:GPG:5264:4725395#v10p265', 2);
INSERT OR REPLACE INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:ya_mutakallim:3', 'GT:idafa_kind:ya_mutakallim', 'إِنَّ وَلِـِّۧيَ ٱللَّهُ ٱلَّذِي نَزَّلَ ٱلۡكِتَٰبَ', 'My protector is God, who sent down the Book — ياء المتكلم open', 'quran', '7:196', 'al:GPG:5264:4725395#v10p265', 3);
INSERT OR REPLACE INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:ya_mutakallim:4', 'GT:idafa_kind:ya_mutakallim', 'قُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ', 'My prayer, my worship, my living and my dying are for God — after a ألف the ياء is open', 'quran', '6:162', 'al:GPG:5264:4725395#v10p265', 4);
INSERT OR REPLACE INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:ya_mutakallim:5', 'GT:idafa_kind:ya_mutakallim', 'مَّآ أَنَا۠ بِمُصۡرِخِكُمۡ وَمَآ أَنتُم بِمُصۡرِخِيَّ', 'Nor can you rescue me — after a sound plural the ياء is open; حمزة read it with كسرة', 'quran', '14:22', 'al:GPG:5264:4725395#v10p265', 5);
INSERT OR REPLACE INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:mubham:2', 'GT:idafa_kind:mubham', 'لا تتعرّف (غير) بإضافتها إلى المعرفة', 'غير does not become definite by being joined to a definite noun — سيبويه and المبرد', 'book', NULL, 'al:GPG:5264:4725394#v10p264', 2);
INSERT OR REPLACE INTO ar_ling_gram_term_example (id, term_id, example_ar, gloss_en, example_kind, qr_ref, source_ref, sort_order) VALUES ('GTX:idafa:iktisab:3', 'GT:idafa_kind:iktisab', 'وفي القرآن آياتٌ لاكتساب التأنيث أكثرُ من آيات اكتساب التذكير', 'In the Qurʾān the first noun takes on the feminine more often than the masculine', 'book', NULL, 'al:GPG:5264:4725393#v10p263', 3);
